DROP TABLE IF EXISTS `roster_request_details`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `roster_request_details` (
  `detail_id` int NOT NULL AUTO_INCREMENT,
  `analytics_id` int NOT NULL,
  `nurse_id` varchar(50) NOT NULL,
  `day` int NOT NULL,
  `request_type` varchar(20) NOT NULL,
  `shift_type` varchar(10) DEFAULT NULL,
  `pair_type` varchar(20) DEFAULT NULL,
  `nurse_2_id` varchar(50) DEFAULT NULL,
  `satisfied` tinyint(1) NOT NULL DEFAULT '0',
  `preference_score` float NOT NULL DEFAULT '0',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`detail_id`),
  KEY `nurse_2_id` (`nurse_2_id`),
  KEY `idx_analytics_id` (`analytics_id`),
  KEY `idx_nurse_id` (`nurse_id`),
  KEY `idx_request_type` (`request_type`),
  KEY `idx_satisfied` (`satisfied`),
  KEY `idx_created_at` (`created_at`),
  CONSTRAINT `roster_request_details_ibfk_1` FOREIGN KEY (`analytics_id`) REFERENCES `roster_analytics` (`analytics_id`) ON DELETE CASCADE,
  CONSTRAINT `roster_request_details_ibfk_2` FOREIGN KEY (`nurse_id`) REFERENCES `nurses` (`nurse_id`) ON DELETE CASCADE,
  CONSTRAINT `roster_request_details_ibfk_3` FOREIGN KEY (`nurse_2_id`) REFERENCES `nurses` (`nurse_id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
